<section class="panel"><div class="panel-heading"><h2><?= e(t('Team accounts')) ?></h2><span class="muted"><?= e(t('Owner has full access')) ?></span></div><div class="table-wrap"><table><thead><tr><th><?= e(t('Name / email')) ?></th><th><?= e(t('Role')) ?></th><th><?= e(t('Status')) ?></th><th><?= e(t('Permissions')) ?></th><th class="table-actions"><?= e(t('Actions')) ?></th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><strong><?= e($u['name']) ?></strong><small><?= e($u['email']) ?></small></td><td><?= $u['role']==='owner'?t('Owner / Super admin'):t('Staff') ?></td><td><span class="badge <?= $u['active']?'purchase':'production' ?>"><?= $u['active']?t('Active'):t('Disabled') ?></span></td><td><?= $u['role']==='owner'?t('All permissions'):count(json_decode($u['permissions'],true)?:[]).t(' granted') ?></td><td class="table-actions"><?php if($u['role']==='staff'): ?><button type="button" class="button small edit-user" data-user="<?= e(json_encode($u)) ?>"><?= e(t('Edit access')) ?></button><?php else: ?><span class="muted"><?= e(t('Full access')) ?></span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel" id="user-editor"><div class="panel-heading"><h2 id="user-form-title"><?= e(t('Add staff account')) ?></h2><button type="button" class="text-button" id="reset-user"><?= e(t('Clear / add new')) ?></button></div><form method="post" action="<?= e(url('users')) ?>" id="user-form"><?= csrf_field() ?><input type="hidden" name="id" value="0"><div class="form-grid"><?php field('name',t('Staff name'),'text','','required maxlength="120"');field('email',t('Email address'),'email','','required maxlength="190" autocomplete="off"');field('password',t('Password'),'password','','required minlength="10" maxlength="72" autocomplete="new-password"'); ?><label class="check"><input type="checkbox" name="active" value="1" checked> <?= e(t('Account active')) ?></label></div><p class="muted" id="password-help"><?= e(t('Password must contain 10–72 characters.')) ?></p><h3><?= e(t('Staff permissions')) ?></h3><p class="muted"><?= e(t('Grant only the operations this staff member should perform.')) ?></p><div class="permission-grid"><?php foreach(permissions() as $key=>$label): if($key==='users.manage') continue; ?><label class="check"><input type="checkbox" name="permissions[]" value="<?= e($key) ?>"> <?= e(t($label)) ?></label><?php endforeach; ?></div><div class="form-footer"><span class="muted"><?= e(t('Only the owner can manage user accounts.')) ?></span><button type="submit" class="button primary"><?= e(t('Save staff account')) ?></button></div></form></section>
